    <style>
        :root {
            --primary: #d97706;
            --primary-light: #fef3c7;
            --bg: #f8fafc;
            --card-bg: #ffffff;
            --text: #1e293b;
            --text-secondary: #64748b;
            --border: #e2e8f0;
            --success: #10b981;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        body {
            background-color: var(--bg);
            color: var(--text);
            padding-bottom: 40px;
        }

        header {
            background: linear-gradient(135deg, #f59e0b, #d97706);
            color: white;
            padding: 24px 16px;
            text-align: center;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
            position: sticky;
            top: 0;
            z-index: 10;
        }

        h1 {
            font-size: 1.5rem;
            margin-bottom: 8px;
        }

        .counter {
            font-size: 0.95rem;
            background: rgba(255, 255, 255, 0.2);
            display: inline-block;
            padding: 4px 12px;
            border-radius: 20px;
            backdrop-filter: blur(4px);
        }

        .container {
            max-width: 600px;
            margin: 0 auto;
            padding: 16px;
        }

        .day-section {
            margin-top: 24px;
        }

        .day-title {
            font-size: 1.2rem;
            font-weight: bold;
            color: var(--primary);
            margin-bottom: 16px;
            padding-bottom: 4px;
            border-bottom: 2px solid var(--primary-light);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .timeline {
            position: relative;
            padding-left: 24px;
        }

        .timeline::before {
            content: '';
            position: absolute;
            left: 7px;
            top: 8px;
            bottom: 8px;
            width: 2px;
            background-color: var(--border);
        }

        .timeline-item {
            position: relative;
            margin-bottom: 20px;
            background: var(--card-bg);
            border-radius: 12px;
            padding: 16px;
            box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05);
            border: 1px solid var(--border);
            transition: all 0.2s ease;
        }

        .timeline-item::before {
            content: '';
            position: absolute;
            left: -21px;
            top: 20px;
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: var(--card-bg);
            border: 2px solid var(--primary);
            z-index: 1;
            transition: all 0.2s ease;
        }

        .timeline-item.completed {
            background-color: #f1f5f9;
            border-color: #cbd5e1;
            opacity: 0.8;
        }

        .timeline-item.completed::before {
            background-color: var(--success);
            border-color: var(--success);
        }

        .timeline-item.completed .item-title,
        .timeline-item.completed .item-time,
        .timeline-item.completed .item-transit {
            text-decoration: line-through;
            color: var(--text-secondary);
        }

        .item-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 8px;
        }

        .item-time {
            font-size: 0.85rem;
            font-weight: 600;
            color: var(--primary);
            background: var(--primary-light);
            padding: 2px 8px;
            border-radius: 4px;
        }

        .item-checkbox {
            width: 22px;
            height: 22px;
            cursor: pointer;
            accent-color: var(--success);
        }

        .item-title {
            font-size: 1.05rem;
            font-weight: bold;
            margin-bottom: 6px;
        }

        .item-transit {
            font-size: 0.85rem;
            color: var(--text-secondary);
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .item-transit::before {
            content: '➔';
            font-size: 0.75rem;
        }
    </style>
</head>
<body>

    <header>
        <h1>台南兩天一夜行程</h1>
        <div class="counter" id="counter">已完成 0 / 11 項</div>
    </header>

    <div class="container" id="app">
        <!-- Day 1 -->
        <div class="day-section">
            <div class="day-title">第一天（週六）</div>
            <div class="timeline">
                <div class="timeline-item" data-id="0">
                    <div class="item-header">
                        <span class="item-time">8:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">台北車站搭高鐵</div>
                    <div class="item-transit">搭乘高鐵南下</div>
                </div>

                <div class="timeline-item" data-id="1">
                    <div class="item-header">
                        <span class="item-time">10:15</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">抵達台南站，轉搭計程車去飯店寄行李</div>
                    <div class="item-transit">轉搭計程車</div>
                </div>

                <div class="timeline-item" data-id="2">
                    <div class="item-header">
                        <span class="item-time">11:00</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">吃牛肉湯當早午餐（現場抽店）</div>
                    <div class="item-transit">步行或在地移動</div>
                </div>

                <div class="timeline-item" data-id="3">
                    <div class="item-header">
                        <span class="item-time">13:00</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">神農街逛老街拍照、喝一杯冰</div>
                    <div class="item-transit">步行</div>
                </div>

                <div class="timeline-item" data-id="4">
                    <div class="item-header">
                        <span class="item-time">15:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">安平古堡、安平老街逛街買蜜餞</div>
                    <div class="item-transit">搭公車</div>
                </div>

                <div class="timeline-item" data-id="5">
                    <div class="item-header">
                        <span class="item-time">18:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">安平晚餐吃蝦捲，搭計程車回市區</div>
                    <div class="item-transit">搭計程車</div>
                </div>

                <div class="timeline-item" data-id="6">
                    <div class="item-header">
                        <span class="item-time">20:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">回飯店休息，想的話再去夜市</div>
                    <div class="item-transit">自由移動</div>
                </div>
            </div>
        </div>

        <!-- Day 2 -->
        <div class="day-section">
            <div class="day-title">第二天（週日）</div>
            <div class="timeline">
                <div class="timeline-item" data-id="7">
                    <div class="item-header">
                        <span class="item-time">9:00</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">飯店退房，行李寄櫃台</div>
                    <div class="item-transit">飯店內</div>
                </div>

                <div class="timeline-item" data-id="8">
                    <div class="item-header">
                        <span class="item-time">9:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">孔廟和附近咖啡店慢慢喝一杯</div>
                    <div class="item-transit">走路</div>
                </div>

                <div class="timeline-item" data-id="9">
                    <div class="item-header">
                        <span class="item-time">12:00</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">午餐吃碗粿加小吃</div>
                    <div class="item-transit">步行</div>
                </div>

                <div class="timeline-item" data-id="10">
                    <div class="item-header">
                        <span class="item-time">14:00</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">去飯店領行李，計程車到台南站</div>
                    <div class="item-transit">計程車</div>
                </div>

                <div class="timeline-item" data-id="11">
                    <div class="item-header">
                        <span class="item-time">15:30</span>
                        <input type="checkbox" class="item-checkbox" onchange="toggleItem(this)">
                    </div>
                    <div class="item-title">搭高鐵回台北（17:15 抵達）</div>
                    <div class="item-transit">高鐵北上</div>
                </div>
            </div>
        </div>
    </div>

    <script>
        const STORAGE_KEY = 'tainan_trip_progress';

        function loadProgress() {
            const saved = localStorage.getItem(STORAGE_KEY);
            if (!saved) return;

            const completedIds = JSON.parse(saved);
            const items = document.querySelectorAll('.timeline-item');

            items.forEach(item => {
                const id = item.getAttribute('data-id');
                if (completedIds.includes(id)) {
                    item.classList.add('completed');
                    item.querySelector('.item-checkbox').checked = true;
                }
            });
            updateCounter();
        }

        function toggleItem(checkbox) {
            const item = checkbox.closest('.timeline-item');
            if (checkbox.checked) {
                item.classList.add('completed');
            } else {
                item.classList.remove('completed');
            }
            saveProgress();
            updateCounter();
        }

        function saveProgress() {
            const items = document.querySelectorAll('.timeline-item');
            const completedIds = [];

            items.forEach(item => {
                if (item.classList.contains('completed')) {
                    completedIds.push(item.getAttribute('data-id'));
                }
            });

            localStorage.setItem(STORAGE_KEY, JSON.stringify(completedIds));
        }

        function updateCounter() {
            const total = document.querySelectorAll('.timeline-item').length;
            const completed = document.querySelectorAll('.timeline-item.completed').length;
            document.getElementById('counter').innerText = `已完成 ${completed} / ${total} 項`;
        }

        // 頁面載入時讀取狀態
        document.addEventListener('DOMContentLoaded', loadProgress);
    </script>
</body>
</html>
